<?php require __DIR__.'/app.php';$q=db()->prepare('SELECT * FROM entries WHERE id=? AND kind=? AND published=1');$q->execute([(int)($_GET['id']??0),$kind]);$item=$q->fetch();if(!$item){http_response_code(404);$title='Not found';}else{$title=$item['title'];}require __DIR__.'/header.php';?><section class="section"><div class="container"><?php if(!$item):?><h1>Page not found</h1><a href="index.php">Return home</a><?php else:?><h1><?=e($item['title'])?></h1><p><?=e($item['summary'])?></p><?php if($img=imagepath($item['image'])):?><img style="max-width:100%" src="<?=e($img)?>" alt="<?=e($item['title'])?>"><?php endif;?><div class="body-copy"><?=e($item['body'])?></div><a class="btn-company mt-4" href="contact.php">Enquire</a><?php endif;?></div></section><?php require __DIR__.'/footer.php';?>